def gen_otu_dict(nex_obj, nexson_version=None):
    """Takes a NexSON object and returns a dict of
    otu_id -> otu_obj
    """
    otu_dict = {}
    for otu_id in nex_obj['data']['otus']:
        otu_dict[otu_id] = nex_obj['data']['otus'][otu_id]
    return otu_dict

